package com.example.entity; import jakarta.persistence.*; import java.time.Instant; @Entity @Table(name="game_sessions") public class GameSession { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long gameSessionId; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="chapter_id", nullable=false) private Chapter chapter; private int questionCount; private int totalStageCount; private int currentStageNumber; private int score; @Enumerated(EnumType.STRING) private GameSessionStatus status; private Instant startedAt; private Instant endedAt; public Long getGameSessionId() { return gameSessionId; } public void setGameSessionId(Long id) { this.gameSessionId = id; } public Chapter getChapter() { return chapter; } public void setChapter(Chapter c) { this.chapter = c; } public int getQuestionCount() { return questionCount; } public void setQuestionCount(int q) { this.questionCount = q; } public int getTotalStageCount() { return totalStageCount; } public void setTotalStageCount(int t) { this.totalStageCount = t; } public int getCurrentStageNumber() { return currentStageNumber; } public void setCurrentStageNumber(int c) { this.currentStageNumber = c; } public int getScore() { return score; } public void setScore(int s) { this.score = s; } public GameSessionStatus getStatus() { return status; } public void setStatus(GameSessionStatus s) { this.status = s; } public Instant getStartedAt() { return startedAt; } public void setStartedAt(Instant s) { this.startedAt = s; } public Instant getEndedAt() { return endedAt; } public void setEndedAt(Instant e) { this.endedAt = e; } }
